 static JSONObject rect(double x,double y,double w,double h)throws Exception{return new JSONObject().put("x",x).put("y",y).put("width",w).put("height",h);}
 static String reply(String value)throws Exception{return new JSONObject().put("choices",new JSONArray().put(new JSONObject().put("message",new JSONObject().put("content",value)).put("finish_reason","stop"))).toString();}
 static JSONObject legacy(SharedPreferences prefs)throws Exception{KeyStore keys=KeyStore.getInstance("AndroidKeyStore");keys.load(null);Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,keys.getKey("chatq-personal-ai-v1",null),new javax.crypto.spec.GCMParameterSpec(128,Base64.decode(prefs.getString("iv",""),Base64.NO_WRAP)));cipher.updateAAD("chatq-personal-ai-v1".getBytes("UTF-8"));return new JSONObject(new String(cipher.doFinal(Base64.decode(prefs.getString("value",""),Base64.NO_WRAP)),"UTF-8"));}
 static void olderSave(SharedPreferences prefs,JSONObject value)throws Exception{KeyStore keys=KeyStore.getInstance("AndroidKeyStore");keys.load(null);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,keys.getKey("chatq-personal-ai-v1",null));c.updateAAD("chatq-personal-ai-v1".getBytes("UTF-8"));prefs.edit().putString("iv",Base64.encodeToString(c.getIV(),Base64.NO_WRAP)).putString("value",Base64.encodeToString(c.doFinal(value.toString().getBytes("UTF-8")),Base64.NO_WRAP)).putString("revision",UUID.randomUUID().toString()).commit();}
